// PLANNER API
// ============================================================================

export const plannerApi = {
  getItems: (params?: PlannerFilters): Promise<PlannerItem[]> => 
    apiClient.get<{ items: PlannerItem[] }>('/api/planner/items/', params).then(res => res.items),

