    notes = repo._read_json()

    updated_count = 0
    skipped_count = 0

    for note in notes:
        if 'activity_history' not in note:
            note['activity_history'] = []

        has_created = any(
            activity.get('type') == 'created' 
            for activity in note.get('activity_history', [])
